# Generated by manage.py generate_test_cases.
from uuid import uuid4

from django.http import HttpResponse
from django.urls import reverse
from django.utils import timezone

from bloomerp.models.communication.instant_messaging import (
    IMConversation,
    IMConversationParticipant,
    IMMessage,
    IMThreadReadPosition,
)
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestReadPositionComponent(BloomerpComponentTestCase):
    """Verify private, monotonic acknowledgements and accurate unread totals."""

    view_name = "components_im_read_position"

    def prepare_messages(self, scenario: RequestScenario) -> None:
        """Create three incoming messages and acknowledge only the first two."""
        self.chat = IMConversation.objects.create(kind="group")
        self.member = IMConversationParticipant.objects.create(
            conversation=self.chat, user=self.normal_user
        )
        other = IMConversationParticipant.objects.create(
            conversation=self.chat, user=self.admin_user
        )
        self.messages = [
            IMMessage.objects.create(
                conversation=self.chat,
                sender=other,
                sequence=sequence,
                body=f"Message {sequence}",
            )
            for sequence in range(1, 4)
        ]
        scenario.view_kwargs = {"conversation_id": self.chat.pk}
        scenario.data = {"message_id": str(self.messages[1].pk)}

    def prepare_stale(self, scenario: RequestScenario) -> None:
        """Simulate an older browser response arriving after a newer acknowledgement."""
        self.prepare_messages(scenario)
        self.member.last_read_message = self.messages[2]
        self.member.save()

    def prepare_left(self, scenario: RequestScenario) -> None:
        """Remove access after rendering but before acknowledging a conversation."""
        self.prepare_messages(scenario)
        self.member.left_at = timezone.now()
        self.member.save()

    def prepare_foreign(self, scenario: RequestScenario) -> None:
        """Reject an ID that does not belong to the requested conversation."""
        self.prepare_messages(scenario)
        scenario.data["message_id"] = str(uuid4())

    def prepare_thread(self, scenario: RequestScenario) -> None:
        """Keep thread read positions independent from the main timeline."""
        self.prepare_messages(scenario)
        self.reply = IMMessage.objects.create(
            conversation=self.chat,
            sender=self.messages[0].sender,
            sequence=4,
            body="Thread reply",
            thread_root=self.messages[0],
        )
        scenario.data = {
            "message_id": str(self.reply.pk),
            "thread_root": str(self.messages[0].pk),
        }

    def prepare_wrong_thread(self, scenario: RequestScenario) -> None:
        """Reject a reply presented as part of another thread."""
        self.prepare_thread(scenario)
        scenario.data["thread_root"] = str(self.messages[1].pk)

    def validate_read_and_count(self, response: HttpResponse) -> bool:
        """Check unread messages beyond the displayed marker and unfiltered orb totals."""
        self.member.refresh_from_db()
        listing = self.client.get(
            reverse("components_im_conversations"), {"q": "not-a-match"}
        )
        return (
            self.member.last_read_message_id == self.messages[1].pk
            and b'data-unread-total="1"' in listing.content
        )

    def validate_stale(self, response: HttpResponse) -> bool:
        """Ensure out-of-order reads never move the marker backward."""
        self.member.refresh_from_db()
        return self.member.last_read_message_id == self.messages[2].pk

    def validate_thread(self, response: HttpResponse) -> bool:
        """Check that reading a thread does not clear unseen timeline messages."""
        self.member.refresh_from_db()
        return (
            self.member.last_read_message_id is None
            and IMThreadReadPosition.objects.get(
                participant=self.member, thread_root=self.messages[0]
            ).last_read_message_id
            == self.reply.pk
        )

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Exercise acknowledgements, races, thread isolation and request restrictions."""
        return [
            RequestScenario(
                name="Read only displayed messages",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_messages,
                expected=ExpectedResult(
                    response_validators=[self.validate_read_and_count]
                ),
            ),
            RequestScenario(
                name="Stale read stays monotonic",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_stale,
                expected=ExpectedResult(response_validators=[self.validate_stale]),
            ),
            RequestScenario(
                name="Track thread separately",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_thread,
                expected=ExpectedResult(response_validators=[self.validate_thread]),
            ),
            RequestScenario(
                name="Wrong thread rejected",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_wrong_thread,
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Foreign marker rejected",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_foreign,
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Former member denied",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_left,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Anonymous denied",
                method="POST",
                prepare=self.prepare_messages,
                expected=ExpectedResult(status_code=302),
            ),
            RequestScenario(
                name="GET does not mark read",
                user=self.normal_user,
                prepare=self.prepare_messages,
                expected=ExpectedResult(status_code=405),
            ),
        ]
